<?php
if(!defined('ABSPATH'))exit;if(!is_user_logged_in()){wp_safe_redirect(wp_login_url(home_url('/my-services/')));exit;}$u=wp_get_current_user();$client=legacyx_find_client_by_wp_user(get_current_user_id());$rows=$client?legacyx_get_client_engagements($client->ID):array();$counts=$client?legacyx_engagement_counts($client->ID):array('total'=>0,'active'=>0,'completed'=>0);get_header();?><main class="legacyx-credit-center"><div class="legacyx-credit-shell"><a class="legacyx-credit-back" href="<?php echo esc_url(home_url('/client-portal/'));?>">← Client Command Center</a><header class="legacyx-credit-head"><div><span class="kicker">LEGACY X FIRM OS · SERVICES</span><h1>My Services</h1><p>Review your active Legacy X Firm advisory engagements, objectives, deliverables and next actions.</p></div><div class="legacyx-credit-identity"><span>Client</span><strong><?php echo esc_html($u->display_name?:$u->user_login);?></strong><?php if($client):?><small><?php echo esc_html(get_post_meta($client->ID,'_legacyx_client_id',true));?></small><?php endif;?></div></header><?php if(!$client):?><div class="legacyx-portal-notice"><strong>Services connection pending.</strong> Your Universal Client Profile must be linked before engagement data can be displayed.</div><?php else:?><section class="legacyx-credit-summary"><div><span>Total Engagements</span><strong><?php echo esc_html($counts['total']);?></strong></div><div><span>Active</span><strong><?php echo esc_html($counts['active']);?></strong></div><div><span>Completed</span><strong><?php echo esc_html($counts['completed']);?></strong></div><div><span>Relationship</span><strong><?php echo esc_html(get_post_meta($client->ID,'_legacyx_service_level',true)?:'Advisory');?></strong></div></section><section class="legacyx-credit-track"><div class="legacyx-track-title"><span>ENGAGEMENT PORTFOLIO</span><h2>Advisory Services</h2><p>Only engagements connected to your Universal Client Profile are displayed.</p></div><div class="legacyx-step-list"><?php if(!$rows):?><article class="legacyx-credit-step"><span class="legacyx-step-num">—</span><div><h3>No service engagements recorded yet</h3><p>Your Legacy X Firm team will add your active advisory services here.</p></div></article><?php else:foreach($rows as $i=>$r):$division=get_post_meta($r->ID,'_legacyx_division',true);$level=get_post_meta($r->ID,'_legacyx_delivery_level',true);$status=get_post_meta($r->ID,'_legacyx_engagement_status',true);$advisor=get_post_meta($r->ID,'_legacyx_advisor',true);$objective=get_post_meta($r->ID,'_legacyx_objective',true);$deliverables=get_post_meta($r->ID,'_legacyx_deliverables',true);$next=get_post_meta($r->ID,'_legacyx_next_action',true);$target=get_post_meta($r->ID,'_legacyx_target_date',true);?><article class="legacyx-credit-step"><span class="legacyx-step-num"><?php echo sprintf('%02d',$i+1);?></span><div><h3><?php echo esc_html(get_the_title($r));?></h3><p><strong><?php echo esc_html($division?:'Advisory');?></strong> · <?php echo esc_html($level?:'Guided');?> · <strong>Status:</strong> <?php echo esc_html($status?:'Proposed');?><?php if($advisor):?><br><strong>Advisor:</strong> <?php echo esc_html($advisor);?><?php endif;?><?php if($target):?> · <strong>Target:</strong> <?php echo esc_html($target);?><?php endif;?><?php if($objective):?><br><strong>Objective:</strong> <?php echo esc_html($objective);?><?php endif;?><?php if($deliverables):?><br><strong>Deliverables:</strong> <?php echo nl2br(esc_html($deliverables));?><?php endif;?><?php if($next):?><br><strong>Next Action:</strong> <?php echo esc_html($next);?><?php endif;?></p></div><b><?php echo esc_html($status==='Completed'?'✓':'→');?></b></article><?php endforeach;endif;?></div></section><?php endif;?></div></main><?php get_footer();?>